import{g as a,ad as n,r as p,A as e}from"./chunks/framework.BdL874pW.js";const _=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"docs/getting-started.md","filePath":"docs/getting-started.md","lastUpdated":1789435632000}'),t={name:"docs/getting-started.md"};function c(l,s,o,i,r,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h1><p>Two paths: the starter template, or a manual setup you can paste into an existing Vite app.</p><p>Requires <strong>Node <code>&gt;=20.19.0</code></strong>, <strong>Vite</strong>, <strong>Vue 3</strong> and <strong>Tailwind CSS <code>&gt;=3.4.0 &lt;4</code></strong>. <code>vue</code>, <code>vue-router</code> and <code>tailwindcss</code> are peer dependencies; install them in your app.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick start”">​</a></h2><p>You can set up <code>frappe-ui</code> with <a href="https://github.com/netchampfaris/frappe-ui-starter" target="_blank" rel="noreferrer"><code>frappe-ui-starter</code></a>. If you already have a Frappe app for which you want to build a frontend, start with <strong>Step 2</strong>.</p><h3 id="create-your-frappe-app" tabindex="-1">Create your Frappe app <a class="header-anchor" href="#create-your-frappe-app" aria-label="Permalink to “Create your Frappe app”">​</a></h3><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">bench</span><span class="s_2575z4"> new-app</span><span class="s_2575z4"> todo</span></span></code></pre></div><h3 id="setup-frappe-ui" tabindex="-1">Setup frappe-ui <a class="header-anchor" href="#setup-frappe-ui" aria-label="Permalink to “Setup frappe-ui”">​</a></h3><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_i592pt">cd</span><span class="s_2575z4"> apps/todo</span></span>
<span class="line"><span class="s_1th9sy"># this will setup a vue project with frappe-ui set up</span></span>
<span class="line"><span class="s_1th9sy"># inside the frontend directory</span></span>
<span class="line"><span class="s_euu481">npx</span><span class="s_2575z4"> degit</span><span class="s_2575z4"> netchampfaris/frappe-ui-starter</span><span class="s_2575z4"> frontend</span></span></code></pre></div><p>Refer <a href="https://github.com/netchampfaris/frappe-ui-starter" target="_blank" rel="noreferrer">frappe-ui-starter</a> for more details.</p><h3 id="ignore-csrf-config" tabindex="-1">Ignore_csrf config <a class="header-anchor" href="#ignore-csrf-config" aria-label="Permalink to “Ignore_csrf config”">​</a></h3><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">bench</span><span class="s_2d41qv"> --site</span><span class="s_2575z4"> todo.test</span><span class="s_2575z4"> set-config</span><span class="s_2575z4"> ignore_csrf</span><span class="s_40mev6"> 1</span></span></code></pre></div><p>This will prevent CSRFToken errors while using the vite dev server. In production environment, the csrf_token is attached to the window object in index.html for you.</p><h3 id="start-dev-server" tabindex="-1">Start dev server <a class="header-anchor" href="#start-dev-server" aria-label="Permalink to “Start dev server”">​</a></h3><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_i592pt">cd</span><span class="s_2575z4"> frontend</span></span>
<span class="line"><span class="s_euu481">yarn</span></span>
<span class="line"><span class="s_euu481">yarn</span><span class="s_2575z4"> dev</span></span></code></pre></div><p>The Vite dev server will start on the port <code>8080</code>. This can be changed from <code>vite.config.js</code>. The development server is configured to proxy your frappe app (usually running on port 8000). If you have a site named <code>todo.test</code>, open <code>http://todo.test:8080</code> in your browser. If you see a button named &quot;Click to send &#39;ping&#39; request&quot;, congratulations!</p><p>If you notice the browser URL is <code>/frontend</code>, this is the base URL where your frontend app will run in production. To change this, open <code>src/router.js</code> and change the base URL passed to <code>createWebHistory</code>.</p><h2 id="manual-setup" tabindex="-1">Manual setup <a class="header-anchor" href="#manual-setup" aria-label="Permalink to “Manual setup”">​</a></h2><p>Five files. Every step below is required; skipping the Tailwind <code>content</code> entry is the single most common cause of an app that renders unstyled.</p><h3 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to “Install”">​</a></h3><p><code>npm create vite@latest</code> currently scaffolds Tailwind v4, which frappe-ui does not support. Replace it:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> uninstall</span><span class="s_2575z4"> tailwindcss</span><span class="s_2575z4"> @tailwindcss/vite</span></span>
<span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> install</span><span class="s_2d41qv"> -D</span><span class="s_2575z4"> tailwindcss@^3.4</span><span class="s_2575z4"> postcss</span><span class="s_2575z4"> autoprefixer</span></span>
<span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> install</span><span class="s_2575z4"> frappe-ui</span><span class="s_2575z4"> vue-router</span></span></code></pre></div><h3 id="vite-config-ts" tabindex="-1"><code>vite.config.ts</code> <a class="header-anchor" href="#vite-config-ts" aria-label="Permalink to “vite.config.ts”">​</a></h3><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">defineConfig</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vite</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> vue</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">@vitejs/plugin-vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> frappeui</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/vite</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_indoxt"> defineConfig</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  plugins</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_indoxt">frappeui</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> frontendRoute</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/todo</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span><span class="s_1jjt6x">,</span><span class="s_indoxt"> vue</span><span class="s_13ahmt">()]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span></code></pre></div><p><code>frontendRoute</code> is the route the app is served on. It drives the dev-server site banner and the production <code>indexHtmlPath</code>.</p><p>Every sub-plugin except <code>lucideIcons</code> and <code>frappeTypes</code> is on by default. Pass <code>false</code> to turn one off. For a prototype with no Frappe backend:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_indoxt">frappeui</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> frappeProxy</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> false</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> jinjaBootData</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> false</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> buildConfig</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> false</span><span class="s_13ahmt"> })</span></span></code></pre></div><p>Add <code>lucideIcons: true</code> only if your own code imports <code>~icons/lucide/*</code> or writes <code>&lt;LucideX /&gt;</code> tags. frappe-ui&#39;s own icons are class names and need nothing from Vite. See <a href="./other/icons">Icons</a>.</p><h3 id="tailwind-config-js" tabindex="-1"><code>tailwind.config.js</code> <a class="header-anchor" href="#tailwind-config-js" aria-label="Permalink to “tailwind.config.js”">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> preset</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">content</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/tailwind</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">/** </span><span class="s_y1rh3e">@type</span><span class="s_1zp9pn"> {</span><span class="s_1b1qqa">import(&#39;tailwindcss&#39;).Config</span><span class="s_1zp9pn">}</span><span class="s_1th9sy"> */</span></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  presets</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_11933w">preset</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  content</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_fjrnv8">...</span><span class="s_11933w">content</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./index.html</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./src/**/*.{vue,js,ts,jsx,tsx}</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>Spread the exported <code>content</code>. Tailwind v3 does not merge a preset&#39;s <code>content</code> into the app config, so frappe-ui&#39;s own source globs have to be listed by the app or none of its utility classes compile. See <a href="./foundations/tailwind">Tailwind Setup</a> for what the preset replaces.</p><h3 id="postcss-config-js" tabindex="-1"><code>postcss.config.js</code> <a class="header-anchor" href="#postcss-config-js" aria-label="Permalink to “postcss.config.js”">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  plugins</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> tailwindcss</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {}</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> autoprefixer</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {}</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><h3 id="src-style-css" tabindex="-1"><code>src/style.css</code> <a class="header-anchor" href="#src-style-css" aria-label="Permalink to “src/style.css”">​</a></h3><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_19y4hp">@</span><span class="s_50ecpt">import</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/style.css</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">;</span></span></code></pre></div><p>That one file emits <code>@tailwind base</code>, <code>@tailwind components</code>, <code>@tailwind utilities</code> and the Inter font import. Adding the directives again emits every Tailwind layer twice.</p><h3 id="src-main-ts" tabindex="-1"><code>src/main.ts</code> <a class="header-anchor" href="#src-main-ts" aria-label="Permalink to “src/main.ts”">​</a></h3><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">createApp</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">router</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./router</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./style.css</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> App</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./App.vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">createApp</span><span class="s_13ahmt">(</span><span class="s_22m8k2">App</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">router</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">.</span><span class="s_indoxt">mount</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">#app</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span></code></pre></div><p><code>app.use(FrappeUI)</code> is optional. It installs the Options API resources surface (<code>this.$resources</code>) when called as <code>app.use(FrappeUI, { resources: true })</code>, and otherwise only adds dev-mode guards for the removed globals.</p><h3 id="src-app-vue" tabindex="-1"><code>src/App.vue</code> <a class="header-anchor" href="#src-app-vue" aria-label="Permalink to “src/App.vue”">​</a></h3><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1i4ay4"> lang</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">ts</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">FrappeUIProvider</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_wac0bt">FrappeUIProvider</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_wac0bt">RouterView</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_wac0bt">FrappeUIProvider</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>FrappeUIProvider</code> renders the <code>dialog.*</code> and <code>toast.*</code> portals and adds no element of its own. Mount exactly one.</p><h3 id="typescript" tabindex="-1">TypeScript <a class="header-anchor" href="#typescript" aria-label="Permalink to “TypeScript”">​</a></h3><p>frappe-ui ships a base config. Extend it: it sets <code>moduleResolution: bundler</code> and <code>allowImportingTsExtensions</code>, which the package needs to resolve its own subpaths.</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_13ahmt">{</span></span>
<span class="line"><span class="s_1xnzz2">  &quot;</span><span class="s_230ye1">extends</span><span class="s_1xnzz2">&quot;</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &quot;</span><span class="s_2575z4">frappe-ui/tsconfig.base.json</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_1xnzz2">  &quot;</span><span class="s_230ye1">compilerOptions</span><span class="s_1xnzz2">&quot;</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_1xnzz2">    &quot;</span><span class="s_i592pt">types</span><span class="s_1xnzz2">&quot;</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">vite/client</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">]</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_1xnzz2">  &quot;</span><span class="s_230ye1">include</span><span class="s_1xnzz2">&quot;</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">src/**/*.ts</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &quot;</span><span class="s_2575z4">src/**/*.vue</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">]</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>Keep <code>types: [&quot;vite/client&quot;]</code>. The package ships TypeScript source, so your compiler checks that source too, and frappe-ui reads <code>import.meta.env</code>. Without it the check fails with <code>Property &#39;env&#39; does not exist on type &#39;ImportMeta&#39;</code>.</p><p>Import types from the same subpath as the value:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">Button</span><span class="s_1jjt6x">,</span><span class="s_50ecpt"> type</span><span class="s_4q1z3w"> ButtonProps</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">Editor</span><span class="s_1jjt6x">,</span><span class="s_50ecpt"> type</span><span class="s_4q1z3w"> RichTextKitOptions</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/editor</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>Only the paths in the package <code>exports</code> map resolve: <code>frappe-ui</code>, <code>frappe-ui/list</code>, <code>frappe-ui/editor</code>, <code>frappe-ui/charts</code>, <code>frappe-ui/icons</code>, <code>frappe-ui/experimental</code>, <code>frappe-ui/tailwind</code>, <code>frappe-ui/vite</code>, <code>frappe-ui/vite/lucideIconsPlugin</code>, <code>frappe-ui/vitepress</code>, <code>frappe-ui/style.css</code> and <code>frappe-ui/tsconfig.base.json</code>. Anything else (<code>frappe-ui/src/...</code>) fails with <code>Package subpath &#39;…&#39; is not defined</code>.</p><h3 id="check-it-works" tabindex="-1">Check it works <a class="header-anchor" href="#check-it-works" aria-label="Permalink to “Check it works”">​</a></h3><p>After <code>npm run dev</code>:</p><ul><li>The page renders in Inter, on semantic surface colors.</li><li>The console has no <code>Package subpath &#39;…&#39; is not defined</code> and no <code>injection &quot;Symbol(router)&quot; not found</code>.</li><li><code>&lt;Button icon-left=&quot;lucide-plus&quot; label=&quot;New&quot; /&gt;</code> shows a plus icon. An empty square means Tailwind is not scanning frappe-ui&#39;s source: check the <code>content</code> array.</li></ul>`,52)])])}const u=a(t,[["render",c]]);export{_ as __pageData,u as default};
